SELECT DISTINCT 
FROM meeting_room mr


        AND mr.status = #{status}


        AND mr.capacity >= #{minCapacity}


        AND mr.capacity <= #{maxCapacity}


        AND (mr.name LIKE CONCAT('%', #{keyword}, '%') OR mr.location LIKE CONCAT('%', #{keyword}, '%'))


        AND mr.id IN (
            SELECT mre.room_id
            FROM meeting_room_equipment mre
            INNER JOIN equipment e ON mre.equipment_id = e.id
            WHERE e.type IN

                #{type}

            GROUP BY mre.room_id
            HAVING COUNT(DISTINCT e.type) = #{equipmentTypes.size}
        )


ORDER BY mr.capacity DESC

SELECT DISTINCT , 
FROM meeting_room mr
LEFT JOIN meeting_room_equipment mre ON mr.id = mre.room_id
LEFT JOIN equipment e ON mre.equipment_id = e.id
WHERE mr.status = 1

    AND mr.capacity >= #{minCapacity}


    AND mr.id IN (
        SELECT mre.room_id
        FROM meeting_room_equipment mre
        INNER JOIN equipment e ON mre.equipment_id = e.id
        WHERE e.type IN

            #{type}

        GROUP BY mre.room_id
        HAVING COUNT(DISTINCT e.type) = #{equipmentTypes.size}
    )

AND mr.id NOT IN (
    SELECT DISTINCT b.room_id
    FROM booking b
    WHERE b.status IN (1, 2)
    AND b.start_time < #{endTime}
    AND b.end_time > #{startTime}

        AND b.id != #{excludeBookingId}

)
ORDER BY mr.capacity DESC

